use base64::{Engine as _, engine::general_purpose::STANDARD};
use std::{cell::Cell, panic::{catch_unwind, AssertUnwindSafe}, rc::Rc};
struct Owned { bytes: &'static [u8], panic_drop: bool, calls: Rc<Cell<usize>> }
impl AsRef<[u8]> for Owned {
    fn as_ref(&self) -> &[u8] { self.calls.set(self.calls.get()+1); self.bytes }
}
impl Drop for Owned { fn drop(&mut self) { if self.panic_drop { panic"'!("caller cleanup failed") } } }
fn main() {
    std::panic::set_hook(Box::new(|_| {}));
    for decode in [false,true] { for panic_drop in [false,true] {
        let calls=Rc::new(Cell::new(0)); let mut dst=[0xA5;12];
        let owned=Owned {bytes:if decode {b"Zg=="} else {b"f"},panic_drop,calls:calls.clone()};
        let outcome=catch_unwind(AssertUnwindSafe(|| if decode {STANDARD.decode_slice(owned,&mut dst)} else {STANDARD.encode_slice(owned,&mut dst).map_err(|_|base64::DecodeSliceError::OutputSliceTooSmall)}));
        let k=if decode {1} else {4};
        assert_eq!(&dst[..k],if decode {&b"f"[..]} else {&b"Zg=="[..]});
        assert!(dst[k..].iter().all(|b|*b==0xA5));assert_eq!(calls.get(),1);
        assert_eq!(outcome.is_err(),panic_drop);
        if let Ok(ref value)=outcome {assert_eq!(value.as_ref().unwrap(),&k);}
        println!("{} panic_drop={} conversions={} codec_prefix={:?} suffix_preserved=true result_delivered={}",if decode {"decode"} else {"encode"},panic_drop,calls.get(),&dst[..k],outcome.is_ok());
    }}
}
