from pathlib import Path
p=Path('src/engine/general_purpose/decode.rs'); s=p.read_text()
s=s.replace('pub(crate) open spec fn canonical_quads_use', '#[verifier::opaque]\\npub(crate) open spec fn canonical_quads_use')
start=s.index('    proof {\\n      if canonical {',s.index('fn decode_complete_quads(')); stop=s.index('    let ghost initial_output',start)
s=s[:start]+'''    proof { if canonical { canonical_quads_bounds(x,input@,decode_table@,input_index_end as nat); } }
'''+s[stop:]
lemmas=[]
for width, quads in [(32,8),(4,1)]:
 start=s.index('        proof {\\n      if canonical {',s.index('while chunk_index',s.index('fn decode_complete_quads(')) if width==32 else s.index('// remaining quads,'))
 stop=s.index('        let chunk_output',start)
 body=s[start:stop]
 body=body[body.index('if canonical {')+len('if canonical {'):]
 body=body[:body.rfind('}')]; body=body[:body.rfind('}')]
 body=body.replace('(input_unrolled_loop_end+chunk_index*4)', 'input_index')
 body=body.replace('input@','input').replace('decode_table@','decode_table').replace('chunk@','chunk')
 n=width//4*3
 ensures='forall|i: int| 0 <= i < '+str(width)+' ==> #[trigger] decode_table[chunk[i] as int] < 64,\\n'
 if width==32:
  for k in range(4):
   ensures+=f'        forall|j: int| 0 <= j < 6 ==> #[trigger] chunk_byte(chunk.subrange({k*8},{k*8+8}),decode_table,j) == x[output_base as int+{k*6}+j],\\n'
 else: ensures+='        forall|j: int| 0 <= j < 3 ==> #[trigger] chunk_byte(chunk,decode_table,j) == x[output_base as int+j],\\n'
 lemma=f'''proof fn prepare_decode_{width}(x: Seq<u8>, input: Seq<u8>, decode_table: Seq<u8>, end: nat,
    input_index: usize, output_base: usize, chunk: Seq<u8>)
    requires canonical_quads_use(x,input,decode_table,end), decode_table.len() == 256,
        input_index % 4 == 0, input_index + {width} <= end <= input.len(),
        output_base == input_index / 4 * 3,
        chunk == input.subrange(input_index as int,input_index as int+{width}),
    ensures {ensures}
{{
    hide(chunk_byte);
    canonical_quads_bounds(x,input,decode_table,end);
    reveal(canonical_quads_use);
{body}
}}
'''
 lemmas.append(lemma)
 ii='input_index' if width==32 else '(input_unrolled_loop_end+chunk_index*4) as usize'
 s=s[:start]+f'''        proof {{ if canonical {{
            prepare_decode_{width}(x,input@,decode_table@,input_index_end as nat,{ii},output_base,chunk@);
        }} }}
'''+s[stop:]
# canonical bounds carries only consumer facts; no encoding expansion in loops
bounds='''proof fn canonical_quads_bounds(x: Seq<u8>, input: Seq<u8>, table: Seq<u8>, end: nat)
    requires canonical_quads_use(x,input,table,end),
    ensures decoder_image(x,input), end / 4 * 3 <= x.len(),
        end <= super::decode_suffix::terminal_input_index(x),
        forall|v: nat| v < 64 ==> table[crate::round_trip_spec::standard_symbol(v) as int] == v as u8,
{
    reveal(canonical_quads_use);
    reveal(decoder_image);
    super::decode_suffix::canonical_suffix_image(x);
}
'''
pos=s.index('#[verifier::verify]',s.index('pub(crate) open spec fn canonical_quads_use'))
s=s[:pos]+bounds+'\\n'.join(lemmas)+s[pos:]
p.write_text(s)
